-- Materi Edukasi Budaya aplikasi mobile kini dikelola dari dashboard (menu Edukasi).
-- Sebelumnya materi dibundel di aplikasi (mobile-app/lib/data/datasources/local/culture_data.dart); keenam materi
-- itu dipindah ke sini agar aplikasi tetap menampilkan isi yang sama setelah memuatnya dari server.
-- timeline/philosophy/images berupa teks JSON; images = kunci foto bawaan aplikasi atau berkas unggahan (pertama = sampul).

-- CreateTable
CREATE TABLE `culture_topics` (
    `id` VARCHAR(60) NOT NULL,
    `title` VARCHAR(80) NOT NULL,
    `category` VARCHAR(40) NOT NULL,
    `summary` VARCHAR(200) NOT NULL,
    `headline` VARCHAR(200) NOT NULL,
    `read_minutes` INTEGER NOT NULL DEFAULT 5,
    `history` TEXT NOT NULL,
    `timeline_title` VARCHAR(60) NOT NULL,
    `timeline` TEXT NOT NULL,
    `philosophy` TEXT NOT NULL,
    `images` TEXT NOT NULL,
    `video_minutes` INTEGER NOT NULL DEFAULT 0,
    `status` ENUM('Terpublikasi', 'Draf') NOT NULL,
    `author` VARCHAR(60) NOT NULL,
    `created_at` DATETIME(3) NOT NULL,
    `updated_at` DATETIME(3) NOT NULL,

    INDEX `culture_topics_status_created_at`(`status`, `created_at`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Materi awal
INSERT INTO `culture_topics` (`id`, `title`, `category`, `summary`, `headline`, `read_minutes`, `history`, `timeline_title`, `timeline`, `philosophy`, `images`, `video_minutes`, `status`, `author`, `created_at`, `updated_at`) VALUES
('wayang-kulit', 'Wayang Kulit', 'Pertunjukan', 'Kisah, tokoh, dan makna bayangan di balik kelir.', 'Seni pertunjukan bayangan warisan budaya dunia dari Jawa.', 8, 'Wayang kulit telah dikenal di Jawa sejak abad ke-10 dan berkembang menjadi media dakwah, pendidikan, dan hiburan. Di Jawa Timur, gaya Jawatimuran memiliki ciri sabetan tegas dan iringan gamelan yang dinamis.', 'Linimasa', '[{"label":"903 M","text":"Prasasti Balitung menyebut pertunjukan \\"mawayang\\" untuk upacara."},{"label":"Abad 15","text":"Wali Songo memakai wayang sebagai sarana dakwah."},{"label":"2003","text":"UNESCO menetapkan wayang sebagai Warisan Budaya Tak Benda."}]', '[{"symbol":"◆","title":"Kelir (layar putih)","text":"Melambangkan dunia tempat manusia menjalani kehidupan."},{"symbol":"☀","title":"Blencong (lampu)","text":"Sumber cahaya kehidupan; tanpa terang, bayangan tak tampak."},{"symbol":"▲","title":"Gunungan","text":"Simbol alam semesta, pembuka dan penutup setiap babak."},{"symbol":"●","title":"Dalang","text":"Pengatur jalannya cerita, cerminan kuasa Sang Pencipta."}]', '["wayang","panggung","gamelan","pendopo"]', 12, 'Terpublikasi', 'Tim Edukasi TKBJ', '2026-11-28 08:00:00.000', '2026-11-28 08:00:00.000'),
('tari-topeng-malangan', 'Tari Topeng Malangan', 'Pertunjukan', 'Karakter topeng Panji dan gerak khas Malang.', 'Tari bertopeng khas Malang yang membawakan kisah Panji.', 6, 'Topeng Malangan berkembang di desa-desa sekitar Malang dan membawakan cerita Panji, kisah Raden Panji dan Dewi Sekartaji. Setiap topeng diukir dari kayu dan diwarnai sesuai watak tokohnya.', 'Jejak Perkembangan', '[{"label":"Asal","text":"Lakon utama bersumber dari cerita Panji era Kediri dan Majapahit."},{"label":"Pusat","text":"Dusun Kedungmonggo, Pakisaji, dikenal sebagai pusat latihan dan pembuatan topeng."},{"label":"Kini","text":"Tampil rutin di Pendopo Agung TKBJ dan festival budaya Malang."}]', '[{"symbol":"◆","title":"Warna topeng","text":"Merah melambangkan amarah; putih dan hijau melambangkan kesucian dan kebijaksanaan."},{"symbol":"▲","title":"Tokoh Panji","text":"Ksatria halus yang sabar dan rendah hati."},{"symbol":"●","title":"Tokoh Klana","text":"Gambaran raja yang dikuasai nafsu dan angkara murka."},{"symbol":"☀","title":"Gerak tari","text":"Gerak tegas dan dinamis mencerminkan watak masyarakat Malang."}]', '["topeng","sanggar","pendopo","gamelan"]', 9, 'Terpublikasi', 'Tim Edukasi TKBJ', '2026-11-28 08:00:01.000', '2026-11-28 08:00:01.000'),
('ketoprak', 'Ketoprak', 'Pertunjukan', 'Teater rakyat dengan cerita sejarah & humor.', 'Teater tradisional Jawa yang memadukan cerita dan gamelan.', 5, 'Ketoprak lahir sebagai hiburan rakyat di Jawa pada awal abad ke-20 dan menyebar ke Jawa Timur. Ceritanya diambil dari babad, legenda, dan kisah kerajaan, dibawakan dengan dialog berbahasa Jawa yang diselingi humor.', 'Linimasa', '[{"label":"Awal 1900-an","text":"Ketoprak lesung dimainkan petani dengan iringan bunyi lesung."},{"label":"1920-an","text":"Mulai diiringi gamelan dan tampil sebagai pertunjukan panggung."},{"label":"Kini","text":"Tampil di radio, televisi, dan Panggung Terbuka TKBJ."}]', '[{"symbol":"◆","title":"Cerita babad","text":"Menghidupkan sejarah agar mudah dipahami masyarakat."},{"symbol":"☀","title":"Humor","text":"Kritik sosial disampaikan lewat canda yang ringan."},{"symbol":"▲","title":"Bahasa Jawa","text":"Melestarikan tingkatan bahasa dan unggah-ungguh."},{"symbol":"●","title":"Gamelan","text":"Mengatur suasana dan pergantian adegan."}]', '["ketoprak","panggung","gamelan","gedung"]', 15, 'Terpublikasi', 'Tim Edukasi TKBJ', '2026-11-28 08:00:02.000', '2026-11-28 08:00:02.000'),
('gamelan', 'Gamelan Slendro Pelog', 'Musik', 'Dua laras utama dan perannya dalam pertunjukan.', 'Ansambel musik tradisional Jawa dengan dua sistem nada.', 7, 'Gamelan adalah ansambel yang terdiri dari gong, kenong, saron, bonang, kendang, dan instrumen lain. Laras slendro memakai lima nada dengan jarak hampir sama, sedangkan pelog memakai tujuh nada dengan jarak berbeda-beda.', 'Linimasa', '[{"label":"Abad 8","text":"Relief Candi Borobudur menggambarkan alat musik mirip gamelan."},{"label":"Keraton","text":"Gamelan berkembang sebagai musik upacara dan seni istana."},{"label":"2021","text":"UNESCO menetapkan gamelan sebagai Warisan Budaya Tak Benda."}]', '[{"symbol":"●","title":"Gong","text":"Penanda akhir siklus lagu, lambang keteraturan."},{"symbol":"◆","title":"Kendang","text":"Pengatur tempo, seperti pemimpin dalam masyarakat."},{"symbol":"▲","title":"Slendro","text":"Bernuansa riang dan gagah."},{"symbol":"☀","title":"Pelog","text":"Bernuansa khidmat dan lembut."}]', '["gamelan","gedung","wayang","pendopo"]', 6, 'Terpublikasi', 'Tim Edukasi TKBJ', '2026-11-28 08:00:03.000', '2026-11-28 08:00:03.000'),
('jaranan-reog', 'Jaranan & Reog', 'Pertunjukan', 'Tari kuda lumping dan kesenian rakyat Jatim.', 'Kesenian rakyat Jawa Timur dengan kuda anyaman dan barongan.', 6, 'Jaranan dimainkan penari yang menunggang kuda tiruan dari anyaman bambu, diiringi kendang, gong, dan terompet. Reog dari Ponorogo menampilkan topeng barongan berhias bulu merak. Keduanya tumbuh sebagai kesenian rakyat di berbagai daerah Jawa Timur.', 'Sebaran', '[{"label":"Kediri","text":"Jaranan berkembang luas di Kediri, Tulungagung, dan Malang."},{"label":"Ponorogo","text":"Reog menjadi ikon kesenian Ponorogo."},{"label":"2024","text":"UNESCO menetapkan Reog Ponorogo sebagai Warisan Budaya Tak Benda."}]', '[{"symbol":"▲","title":"Kuda kepang","text":"Simbol semangat dan keberanian prajurit."},{"symbol":"◆","title":"Barongan","text":"Kekuatan besar yang harus dikendalikan."},{"symbol":"●","title":"Kendang & gong","text":"Membangun irama yang menghentak."},{"symbol":"☀","title":"Kebersamaan","text":"Dimainkan beramai-ramai oleh warga desa."}]', '["jaranan","panggung","gamelan","parkir"]', 10, 'Terpublikasi', 'Tim Edukasi TKBJ', '2026-11-28 08:00:04.000', '2026-11-28 08:00:04.000'),
('arsitektur-joglo', 'Arsitektur Joglo', 'Arsitektur', 'Filosofi atap Pendopo Agung TKBJ.', 'Bangunan tradisional Jawa dengan atap tinggi dan soko guru.', 4, 'Joglo adalah bangunan tradisional Jawa dengan atap tinggi di bagian tengah yang ditopang empat tiang utama (soko guru). Pendopo Agung TKBJ memakai konsep ruang terbuka ini sehingga penonton dapat menyaksikan pertunjukan dari berbagai sisi.', 'Bagian Rumah Joglo', '[{"label":"Pendopo","text":"Bagian depan yang terbuka untuk menerima tamu dan pertunjukan."},{"label":"Pringgitan","text":"Ruang peralihan, tempat pertunjukan wayang digelar."},{"label":"Dalem","text":"Ruang keluarga dan bagian paling privat."}]', '[{"symbol":"▲","title":"Atap tinggi","text":"Semakin tinggi, semakin dekat dengan Sang Pencipta."},{"symbol":"●","title":"Soko guru","text":"Empat tiang utama melambangkan empat arah mata angin."},{"symbol":"◆","title":"Ruang terbuka","text":"Keterbukaan dan keramahan kepada tamu."},{"symbol":"☀","title":"Tumpang sari","text":"Susunan balok bertingkat yang menopang atap."}]', '["pendopo","panggung","gedung","parkir"]', 4, 'Terpublikasi', 'Tim Edukasi TKBJ', '2026-11-28 08:00:05.000', '2026-11-28 08:00:05.000');
